using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Creates a prompt that asks the model to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional style: 'bullets', 'paragraph', or 'oneliner'. Defaults to 'paragraph'.")] string? style = "paragraph")
    {
        var systemInstruction = style switch
        {
            "bullets" => "Summarize the following text as a concise bullet-point list.",
            "oneliner" => "Summarize the following text in a single sentence.",
            _ => "Summarize the following text in a short paragraph."
        };

        return new GetPromptResult
        {
            Description = "Summarize the provided text.",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new TextContentBlock { Text = $"{systemInstruction}\n\n{text}" }
                }
            ]
        };
    }
}

