+public sealed class ApiFetchTool
+{
+    [McpServerTool(Name = "fetch_post"), Description("Fetches a post by ID from the JSONPlaceholder API.")]
+    public static async Task<string> FetchPostAsync(
+        IHttpClientFactory httpClientFactory,
+        [Description("The numeric ID of the post to retrieve.")] int postId,
+        CancellationToken cancellationToken)
+    {
+        using var client = httpClientFactory.CreateClient("Api");
+        var response = await client.GetAsync($"posts/{postId}", cancellationToken);
+        response.EnsureSuccessStatusCode();
+        return await response.Content.ReadAsStringAsync(cancellationToken);
+    }
+}
